import{_ as e,o as r,c as o,a as s}from"./chunks/plugin-vue_export-helper.B1AaF8Z1.js";const g=JSON.parse('{"title":"BDD, SpecDD, SPDD — говно","description":"","frontmatter":{"site":"pro","title":"BDD, SpecDD, SPDD — говно","date":"2026-10-31T00:00:00.000Z","source":"https://t.me/jfyi_ps/122","head":[["link",{"rel":"canonical","href":"https://oleg-sidorkin.ru/posts/2026-10-31-bdd-specdd-spdd-govno"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"BDD, SpecDD, SPDD — говно"}],["meta",{"property":"og:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"property":"og:url","content":"https://oleg-sidorkin.ru/posts/2026-10-31-bdd-specdd-spdd-govno"}],["meta",{"property":"og:image","content":"https://oleg-sidorkin.ru/og.png"}],["meta",{"property":"og:site_name","content":"Oleg Sidorkin"}],["meta",{"property":"og:locale","content":"ru_RU"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"BDD, SpecDD, SPDD — говно"}],["meta",{"name":"twitter:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"name":"twitter:image","content":"https://oleg-sidorkin.ru/og.png"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BlogPosting\\",\\"headline\\":\\"BDD, SpecDD, SPDD — говно\\",\\"description\\":\\"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы.\\",\\"url\\":\\"https://oleg-sidorkin.ru/posts/2026-10-31-bdd-specdd-spdd-govno\\",\\"inLanguage\\":\\"ru-RU\\",\\"author\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"Oleg Sidorkin\\",\\"alternateName\\":\\"alterfo\\",\\"url\\":\\"https://oleg-sidorkin.ru\\",\\"jobTitle\\":\\"Software Engineer\\",\\"knowsAbout\\":[\\"Music\\",\\"Audio DSP\\",\\"AI\\",\\"RAG\\",\\"Frontend Development\\",\\"Solution Architecture\\"],\\"sameAs\\":[\\"https://github.com/alterfo\\"]},\\"datePublished\\":\\"2026-10-31\\"}"]]},"headers":[],"relativePath":"posts/2026-10-31-bdd-specdd-spdd-govno.md","filePath":"posts/2026-10-31-bdd-specdd-spdd-govno.md"}'),a={name:"posts/2026-10-31-bdd-specdd-spdd-govno.md"};function p(n,t,i,d,c,l){return r(),o("div",null,[...t[0]||(t[0]=[s('<p>В мае 2026-го я подписался на клод. Тогда все ИИ глючили при переполнении контекста. Работать с чем-то больше скрипта на 100 строк было адом. Но клод был первым кто мало-мальски писал рабочий код. Сейчас qwen3.8 27b развернутый у меня локально показывает те же результаты что клод тогда. Да, меня тоже забанили, и я не переживаю по этому поводу ни секунды.</p><p>Примерно в то же время появилась статья и потуги Мартина Фаулера по популяризации подходов с хранением спецификации рядом с кодом.</p><p>В качестве подопытного я тогда решил сделать браузерную игру по мотивам Космических рейнджеров. И сделал - <a href="https://setka.ru/redirect?to=https%3A%2F%2Falterfo.github.io%2Fvacuum-rogues%2F" target="_blank" rel="noreferrer">https://setka.ru/redirect?to=https%3A%2F%2Falterfo.github.io%2Fvacuum-rogues%2F</a></p><p>Потом написал несколько статей на хабр: Когда контекстное окно кончается, а проект - нет: <a href="https://setka.ru/redirect?to=https%3A%2F%2Fhabr.com%2Fru%2Farticles%2F1050728%2F" target="_blank" rel="noreferrer">https://setka.ru/redirect?to=https%3A%2F%2Fhabr.com%2Fru%2Farticles%2F1050728%2F</a> Нейросеть-автопилот вместо 400 тестов: <a href="https://setka.ru/redirect?to=https%3A%2F%2Fhabr.com%2Fru%2Farticles%2F1056722%2F" target="_blank" rel="noreferrer">https://setka.ru/redirect?to=https%3A%2F%2Fhabr.com%2Fru%2Farticles%2F1056722%2F</a> Подавался спикером на HolyJS, но из комиссии это оказалось никому не интересно.</p><p>Актуальные по сей день выводы: — нейросети нельзя дать скриншот и сказать &quot;сделай так же&quot;. Нужно подробно описать где что, как себя ведёт. Максимально подробным языком. Поэтому я не верю в клоны фотошопа. — как следствие - тестировать тоже нужно своими глазами и руками, а потом описывать что не так, и как надо. В интерфейсе есть кривой крестик, я нарочно не лезу руками его исправлять, тестирую VL-модели. — BDD, SpecDD, SPDD (спецификация рядом с кодом) - с самого начала стали не работать ввиду масштаба. В итоге я даже комментарии из кода удалил и запретил. Gitnexus помог отрефакторить файл на 5000 строк (сейчас нейросети уже пишут питон-скрипт для парсинга таких файлов, рефачить уже неактуально). RTK сократил вывод команд. Код - источник истины. Меняют истину только планы. — Покрытие тестами сумасшедшее. Более того, на базе e2e-тестов я обучил ML-модель, которая сейчас выполняет роль авто-пилота, но также используется для поиска баго экономики свободного мира (обидно когда на втором игровом году внезапно падает рейтинг). — При обучении модели-автопилота собрал все возможные грабли обучения модели и сбора датасета.</p><p>Что в итоге: — Движок написан и оттестирован, экономика проработана с помощью всех видов регрессий и бустов и протестирована тысячами прогонов авто-пилотом. — ML-модель обучена и в игре есть авто-пилот который летает, торгует и воюет. Сбегает когда надо. — Исходники: <a href="https://setka.ru/redirect?to=https%3A%2F%2Fgithub.com%2Falterfo%2Fvacuum-rogues" target="_blank" rel="noreferrer">https://setka.ru/redirect?to=https%3A%2F%2Fgithub.com%2Falterfo%2Fvacuum-rogues</a> — Потратил я на неё 3 месяца вечеров.</p><p>Если есть такие же фанаты Космических рейнджеров как я, предлагаю довести игру до ума вместе. Сейчас неинтуитивно для тех, кто не играл в ту. Нужно сделать онбординг, наполнить качественным контентом, проработать дизайн. В общем, всё то, что я даже за деньги обычно не делаю.</p>',7)])])}const h=e(a,[["render",p]]);export{g as __pageData,h as default};
